namespace sv_ba8e3e483b084756a73245c2f3a4d4aa.Services;

/// <summary>
/// Scoped service (per-circuit) that holds the currently selected warehouse
/// and notifies subscribers when the selection changes.
/// </summary>
public sealed class WarehouseStateService
{
    public static readonly IReadOnlyList<(string Id, string Name)> AvailableWarehouses =
    [
        ("wh-a", "Warehouse A"),
        ("wh-b", "Warehouse B"),
        ("wh-c", "Warehouse C"),
    ];

    private string _currentWarehouseId = AvailableWarehouses[0].Id;

    public string CurrentWarehouseId => _currentWarehouseId;

    public string CurrentWarehouseName =>
        AvailableWarehouses.First(w => w.Id == _currentWarehouseId).Name;

    public event Func<Task>? OnWarehouseChanged;

    public async Task SetWarehouseAsync(string warehouseId)
    {
        if (_currentWarehouseId == warehouseId) return;

        _currentWarehouseId = warehouseId;

        if (OnWarehouseChanged is not null)
        {
            await OnWarehouseChanged.Invoke();
        }
    }
}

namespace sv_ba8e3e483b084756a73245c2f3a4d4aa.Services;

/// <summary>
/// Scoped service (per-circuit) that polls for low-stock alerts and
/// notifies all subscribed components when new data arrives.
/// </summary>
public sealed class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentLowStockCount { get; private set; }

    public event Func<Task>? OnAlertCountChanged;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
    }

    /// <summary>
    /// Simulates a database query — returns a random number between 0 and 15.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = Random.Shared.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Called by components to start polling. Uses reference counting so
    /// polling runs as long as at least one subscriber is active.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Called by components when they no longer need polling.
    /// Stops the timer when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            _cts?.Cancel();
            _timer?.Dispose();
            _timer = null;
            _cts?.Dispose();
            _cts = null;
        }
    }

    /// <summary>
    /// Immediately fetches new data and notifies subscribers.
    /// Useful when the warehouse changes and we want instant feedback.
    /// </summary>
    public async Task RefreshAsync()
    {
        CurrentLowStockCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        if (OnAlertCountChanged is not null)
        {
            await OnAlertCountChanged.Invoke();
        }
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start
        await RefreshAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
                    break;

                await RefreshAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _timer?.Dispose();
        _cts?.Dispose();
    }
}

