@using sv_ba8e3e483b084756a73245c2f3a4d4aa.Services
@inject WarehouseStateService WarehouseState
@implements IDisposable

<select class="form-select form-select-sm" value="@WarehouseState.CurrentWarehouseId"
        @onchange="OnWarehouseSelected" style="max-width: 200px;">
    @foreach (var wh in WarehouseStateService.AvailableWarehouses)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
    }

    private async Task OnWarehouseSelected(ChangeEventArgs e)
    {
        var warehouseId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(warehouseId))
        {
            await WarehouseState.SetWarehouseAsync(warehouseId);
        }
    }

    private async Task HandleWarehouseChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
    }
}

