@page "/dashboard"
@rendermode InteractiveServer
@using sv_ba8e3e483b084756a73245c2f3a4d4aa.Services
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Dashboard - @WarehouseState.CurrentWarehouseName</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mt-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">@WarehouseState.CurrentWarehouseName</p>
                <p class="text-muted">ID: @WarehouseState.CurrentWarehouseId</p>
            </div>
        </div>
    </div>

    <div class="col-md-6">
        <div class="card @AlertCardClass">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text fs-1 fw-bold">@AlertService.CurrentLowStockCount</p>
                <p class="text-muted">Items below minimum level (refreshes every 10s)</p>
            </div>
        </div>
    </div>
</div>

@code {
    private string AlertCardClass => AlertService.CurrentLowStockCount > 5
        ? "border-danger" : AlertService.CurrentLowStockCount > 0
        ? "border-warning" : "border-success";

    protected override void OnInitialized()
    {
        AlertService.OnAlertCountChanged += HandleAlertChanged;
        WarehouseState.OnWarehouseChanged += HandleWarehouseChanged;
        AlertService.StartPolling();
    }

    private async Task HandleAlertChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    private async Task HandleWarehouseChanged()
    {
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        AlertService.OnAlertCountChanged -= HandleAlertChanged;
        WarehouseState.OnWarehouseChanged -= HandleWarehouseChanged;
        AlertService.StopPolling();
    }
}

